(* The representation of a deflate stream in the proofs of deflate.c and trees.c (zlib 1.3.2, patched).

   - z_stream: the record SS, its value ss_val (all fields; pointers as val, numbers as Z).
   - struct internal_state (deflate_state): the record DS, its value ds_val.  Every scalar field is a number
     (deflateInit2_ zeroes the whole struct before setting fields), pointers are vals.
   - The three trees inside the state (dyn_ltree, dyn_dtree, bl_tree) are lists of ct entries.  A ct_data is
     two unions of two unsigned shorts each: fc = {freq, code}, dl = {dad, len}.  VST represents a union by
     the member written last (reptype = val + val), and reads only that member: an entry records which one
     (CF/CC for fc, CD/CL for dl).  zmemzero leaves the first members (freq, dad) = 0.
   All of it at the joint compspecs DCS.CS. *)
Require Import VST.floyd.proofauto.
Require Import Zlib.proof.deflate.DCS.
Require Import Zlib.deflate.code.

#[export] Existing Instance DCS.CS.

Definition t_strm := Tstruct _z_stream_s noattr.
Definition t_ds := Tstruct _internal_state noattr.
Definition t_ct := Tstruct _ct_data_s noattr.
Definition t_td := Tstruct _tree_desc_s noattr.
Definition t_gz := Tstruct _gz_header_s noattr.

(* ---------------------------------------------------------------------------------------------------------- *)
(* ct entries *)

Inductive fcv := CF (freq: Z) | CC (code: Z).
Inductive dlv := CD (dad: Z) | CL (len: Z).
Definition ctv : Type := (fcv * dlv)%type.

Definition fc_val (x: fcv) : val + val :=
  match x with CF f => inl (Vint (Int.repr f)) | CC c => inr (Vint (Int.repr c)) end.
Definition dl_val (x: dlv) : val + val :=
  match x with CD d => inl (Vint (Int.repr d)) | CL l => inr (Vint (Int.repr l)) end.
Definition ct_val (x: ctv) : reptype t_ct := (fc_val (fst x), dl_val (snd x)).
Definition ct_vals (l: list ctv) : list (reptype t_ct) := map ct_val l.

(* the zeroed entry *)
Definition ct0 : ctv := (CF 0, CD 0).

(* the numbers in an entry, whatever member is active *)
Definition fc_num (x: fcv) : Z := match x with CF f => f | CC c => c end.
Definition dl_num (x: dlv) : Z := match x with CD d => d | CL l => l end.
Definition ush_ok (z: Z) : Prop := 0 <= z <= 65535.
Definition ct_ok (x: ctv) : Prop := ush_ok (fc_num (fst x)) /\ ush_ok (dl_num (snd x)).

Definition vi (z: Z) : val := Vint (Int.repr z).
Definition vl (z: Z) : val := Vlong (Int64.repr z).

(* ---------------------------------------------------------------------------------------------------------- *)
(* z_stream *)

Record SS := mkSS {
  ss_next_in: val; ss_avail_in: Z; ss_total_in: Z;
  ss_next_out: val; ss_avail_out: Z; ss_total_out: Z;
  ss_msg: val; ss_state: val; ss_zalloc: val; ss_zfree: val; ss_opaque: val;
  ss_data_type: Z; ss_adler: Z; ss_reserved: Z
}.

Definition ss_val (s: SS) : reptype t_strm :=
  (ss_next_in s, (vi (ss_avail_in s), (vl (ss_total_in s), (ss_next_out s, (vi (ss_avail_out s), (vl
  (ss_total_out s), (ss_msg s, (ss_state s, (ss_zalloc s, (ss_zfree s, (ss_opaque s, (vi (ss_data_type s), (vl
  (ss_adler s), vl (ss_reserved s)))))))))))))).

(* ranges of the numeric fields *)
Definition ss_ok (s: SS) : Prop :=
  0 <= ss_avail_in s <= Int.max_unsigned /\ 0 <= ss_total_in s <= Int64.max_unsigned /\
  0 <= ss_avail_out s <= Int.max_unsigned /\ 0 <= ss_total_out s <= Int64.max_unsigned /\
  Int.min_signed <= ss_data_type s <= Int.max_signed /\ 0 <= ss_adler s <= Int64.max_unsigned /\
  0 <= ss_reserved s <= Int64.max_unsigned.

(* ---------------------------------------------------------------------------------------------------------- *)
(* tree_desc *)

Record TD := mkTD { td_dyn_tree: val; td_max_code: Z; td_stat_desc: val }.
Definition td_val (d: TD) : reptype t_td :=
  (td_dyn_tree d, (Vint (Int.repr (td_max_code d)), td_stat_desc d)).

(* ---------------------------------------------------------------------------------------------------------- *)
(* deflate_state *)

Record DS := mkDS {
  ds_strm: val; ds_status: Z; ds_pending_buf: val; ds_pending_buf_size: Z; ds_pending_out: val;
  ds_pending: Z; ds_wrap: Z; ds_gzhead: val; ds_gzindex: Z; ds_method: Z; ds_last_flush: Z;
  ds_w_size: Z; ds_w_bits: Z; ds_w_mask: Z; ds_window: val; ds_window_size: Z; ds_prev: val; ds_head: val;
  ds_ins_h: Z; ds_hash_size: Z; ds_hash_bits: Z; ds_hash_mask: Z; ds_hash_shift: Z; ds_block_start: Z;
  ds_match_length: Z; ds_prev_match: Z; ds_match_available: Z; ds_strstart: Z; ds_match_start: Z;
  ds_lookahead: Z; ds_prev_length: Z; ds_max_chain_length: Z; ds_max_lazy_match: Z; ds_level: Z;
  ds_strategy: Z; ds_good_match: Z; ds_nice_match: Z;
  ds_dyn_ltree: list ctv; ds_dyn_dtree: list ctv; ds_bl_tree: list ctv;
  ds_l_desc: TD; ds_d_desc: TD; ds_bl_desc: TD;
  ds_bl_count: list Z; ds_heap: list Z; ds_heap_len: Z; ds_heap_max: Z; ds_depth: list Z;
  ds_sym_buf: val; ds_lit_bufsize: Z; ds_sym_next: Z; ds_sym_end: Z; ds_opt_len: Z; ds_static_len: Z;
  ds_matches: Z; ds_insert: Z; ds_bi_buf: Z; ds_bi_valid: Z; ds_bi_used: Z; ds_high_water: Z; ds_slid: Z
}.

Definition ds_val (s: DS) : reptype t_ds :=
  (ds_strm s, (vi (ds_status s), (ds_pending_buf s, (vl (ds_pending_buf_size s), (ds_pending_out s, (vl
  (ds_pending s), (vi (ds_wrap s), (ds_gzhead s, (vl (ds_gzindex s), (vi (ds_method s), (vi (ds_last_flush s),
  (vi (ds_w_size s), (vi (ds_w_bits s), (vi (ds_w_mask s), (ds_window s, (vl (ds_window_size s), (ds_prev s,
  (ds_head s, (vi (ds_ins_h s), (vi (ds_hash_size s), (vi (ds_hash_bits s), (vi (ds_hash_mask s), (vi
  (ds_hash_shift s), (vl (ds_block_start s), (vi (ds_match_length s), (vi (ds_prev_match s), (vi
  (ds_match_available s), (vi (ds_strstart s), (vi (ds_match_start s), (vi (ds_lookahead s), (vi (ds_prev_length
  s), (vi (ds_max_chain_length s), (vi (ds_max_lazy_match s), (vi (ds_level s), (vi (ds_strategy s), (vi
  (ds_good_match s), (vi (ds_nice_match s), (ct_vals (ds_dyn_ltree s), (ct_vals (ds_dyn_dtree s), (ct_vals
  (ds_bl_tree s), (td_val (ds_l_desc s), (td_val (ds_d_desc s), (td_val (ds_bl_desc s), (map vi (ds_bl_count s),
  (map vi (ds_heap s), (vi (ds_heap_len s), (vi (ds_heap_max s), (map vi (ds_depth s), (ds_sym_buf s, (vi
  (ds_lit_bufsize s), (vi (ds_sym_next s), (vi (ds_sym_end s), (vl (ds_opt_len s), (vl (ds_static_len s), (vi
  (ds_matches s), (vi (ds_insert s), (vi (ds_bi_buf s), (vi (ds_bi_valid s), (vi (ds_bi_used s), (vl
  (ds_high_water s), vi (ds_slid s))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))).

